class TemperatureConverter {
    // Static utility method: Celsius to Fahrenheit
    public static double celsiusToFahrenheit(double celsius) {
        return (celsius * 9.0 / 5.0) + 32.0;
    }

    // Static utility method: Fahrenheit to Celsius
    public static double fahrenheitToCelsius(double fahrenheit) {
        return (fahrenheit - 32.0) * 5.0 / 9.0;
    }

    // Static helper method checking freezing point
    public static boolean isFreezing(double celsius) {
        return celsius <= 0.0;
    }
}

public class Main {
    public static void main(String[] args) {
        // Zero objects created! Called directly via class name:
        double f = TemperatureConverter.celsiusToFahrenheit(100.0);
        System.out.println("100 C in Fahrenheit: " + f + " F");

        double c = TemperatureConverter.fahrenheitToCelsius(68.0);
        System.out.println("68 F in Celsius: " + c + " C");

        System.out.println("Is -5 C freezing? " + TemperatureConverter.isFreezing(-5.0));
    }
}

