class Point2D {
    private int x;
    private int y;

    // Private constructor forces instantiation through static factory methods
    private Point2D(int x, int y) {
        this.x = x;
        this.y = y;
    }

    // Static Factory Method 1: Origin (0, 0)
    public static Point2D atOrigin() {
        return new Point2D(0, 0);
    }

    // Static Factory Method 2: Custom coordinates
    public static Point2D of(int x, int y) {
        return new Point2D(x, y);
    }

    public void printCoordinates() {
        System.out.println("Point: (" + x + ", " + y + ")");
    }
}

public class Main {
    public static void main(String[] args) {
        Point2D origin = Point2D.atOrigin();
        Point2D custom = Point2D.of(15, 30);

        origin.printCoordinates();
        custom.printCoordinates();
    }
}

