class SimpleMath {
    public static int abs(int num) {
        return num < 0 ? -num : num;
    }
}

public class Main {
    public static void main(String[] args) {
        System.out.println("Absolute: " + SimpleMath.abs(-42));
    }
}

class StringHelpers {
    private StringHelpers() {}

    public static boolean isBlank(String s) {
        return s == null || s.trim().isEmpty();
    }

    public static String truncate(String s, int maxLen) {
        if (s == null) return "";
        if (s.length() <= maxLen) return s;
        return s.substring(0, maxLen) + "...";
    }
}

public class Main {
    public static void main(String[] args) {
        boolean b = StringHelpers.isBlank("   ");
        String t = StringHelpers.truncate("Introduction to OOP", 9);
        System.out.println("Blank: " + b + " | Truncated: " + t);
    }
}

class CurrencyExchange {
    private CurrencyExchange() {}

    public static double usdToEur(double usd, double rate) {
        if (usd <= 0.0 || rate <= 0.0) return 0.0;
        return usd * rate;
    }
}

public class Main {
    public static void main(String[] args) {
        double eur = CurrencyExchange.usdToEur(150.0, 0.92);
        System.out.println("150.0 USD = " + eur + " EUR");
    }
}

