class StudentRecord {
    public String name;
    public int score;

    public StudentRecord(String name, int score) {
        this.name = name;
        this.score = score;
    }

    public static void printSummary(StudentRecord s) {
        if (s != null) {
            System.out.println("Summary: " + s.name + " scored " + s.score);
        }
    }
}

public class Main {
    public static void main(String[] args) {
        StudentRecord s = new StudentRecord("Priya", 95);
        StudentRecord.printSummary(s);
    }
}

class AccountEntity {
    private String holder;
    private double balance;
    private String type;

    private AccountEntity(String holder, double balance, String type) {
        this.holder = holder;
        this.balance = balance;
        this.type = type;
    }

    public static AccountEntity createStandard(String holder, double deposit) {
        return new AccountEntity(holder, deposit >= 0 ? deposit : 0.0, "STANDARD");
    }

    public static AccountEntity createPremium(String holder, double deposit) {
        double bal = deposit >= 5000.0 ? deposit : 5000.0;
        return new AccountEntity(holder, bal, "PREMIUM");
    }

    public String getSummary() {
        return "Created " + type + " account for " + holder + " with $" + balance;
    }
}

public class Main {
    public static void main(String[] args) {
        AccountEntity acc = AccountEntity.createStandard("Ali", 500.0);
        System.out.println(acc.getSummary());
    }
}
